widget.solution:
#include <stdexcept>

class Quote {
public:
    Quote(double bid, double ask) : bid_(bid), ask_(ask) {
        if (bid_ >= ask_) throw std::invalid_argument("bid must be below ask");
    }

    double mid() const { return (bid_ + ask_) / 2; }
    double spread() const { return ask_ - bid_; }

private:
    double bid_;
    double ask_;
};

