widget.solution:
#include <stdexcept>
#include <string>

enum class State { New, Filled, Cancelled };

class Order {
public:
    explicit Order(int qty) : qty_(qty) {
        if (qty_ <= 0) throw std::invalid_argument("quantity must be positive");
    }

    void fill(int q) {
        if (state_ != State::New) throw std::logic_error("order is not live");
        if (q <= 0 || filled_ + q > qty_) throw std::invalid_argument("bad fill");
        filled_ += q;
        if (filled_ == qty_) state_ = State::Filled;
    }

    void cancel() {
        if (state_ != State::New) throw std::logic_error("order is not live");
        state_ = State::Cancelled;
    }

    int filled() const { return filled_; }
    int remaining() const { return qty_ - filled_; }
    std::string state() const {
        if (state_ == State::New) return "new";
        if (state_ == State::Filled) return "filled";
        return "cancelled";
    }

private:
    int qty_;
    int filled_ = 0;
    State state_ = State::New;
};

